#!/usr/bin/env python3
import sys, json

def text_of(content):
    out = []
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        for b in content:
            if not isinstance(b, dict):
                out.append(str(b)); continue
            t = b.get("type")
            if t == "text":
                out.append(b.get("text",""))
            elif t == "thinking":
                out.append("[THINKING] " + b.get("thinking",""))
            elif t == "tool_use":
                name = b.get("name","")
                inp = b.get("input",{})
                out.append(f"[TOOL_USE {name}] " + json.dumps(inp)[:4000])
            elif t == "tool_result":
                c = b.get("content","")
                out.append("[TOOL_RESULT] " + (text_of(c) if not isinstance(c,str) else c)[:6000])
            else:
                out.append(json.dumps(b)[:2000])
    return "\n".join(out)

fn = sys.argv[1]
with open(fn, errors="replace") as fh:
    for i, line in enumerate(fh, 1):
        line = line.strip()
        if not line:
            continue
        try:
            d = json.loads(line)
        except Exception:
            continue
        typ = d.get("type","")
        msg = d.get("message",{})
        role = msg.get("role", typ) if isinstance(msg, dict) else typ
        content = msg.get("content","") if isinstance(msg, dict) else ""
        ts = d.get("timestamp","")
        txt = text_of(content)
        if txt.strip():
            print(f"===== L{i} [{role}] {ts} =====")
            print(txt)
            print()

